ertime})]}),/*#__PURE__*/_jsxs("div",{children:[/*#__PURE__*/_jsx("label",{style:{fontSize:"0.75rem",color:"#64748b",marginBottom:"0.25rem",display:"block"},children:"Task Status"}),/*#__PURE__*/_jsxs("select",{value:task.task||"Accepted",onChange:e=>handleTaskChange(index,e.target.value),style:{width:"100%",padding:"0.5rem",borderRadius:"0.5rem",border:"1px solid #d1d5db",fontSize:"0.875rem"},children:[/*#__PURE__*/_jsx("option",{value:"Accepted",children:"Accepted"}),/*#__PURE__*/_jsx("option",{value:"Not Accepted",children:"Not Accepted"})]})]})]}),/*#__PURE__*/_jsxs("div",{style:{display:"flex",alignItems:"center",gap:"1rem",marginBottom:"1rem",flexWrap:"wrap"},children:[/*#__PURE__*/_jsxs("label",{style:{display:"flex",alignItems:"center",gap:"0.5rem",cursor:"pointer"},children:[/*#__PURE__*/_jsx("input",{type:"checkbox",checked:task.samplePickedUp||false,onChange:e=>handleCheckboxChange(index,e.target.checked),style:{marginRight:"0.25rem"}}),/*#__PURE__*/_jsx("span",{style:{fontSize:"0.875rem",fontWeight:"500"},children:task.samplePickedUp?"Sample Picked Up":"Mark as Picked Up"})]}),task.samplePickedUpTime&&/*#__PURE__*/_jsxs("span",{style:{fontSize:"0.75rem",color:"#16a34a",backgroundColor:"#dcfce7",padding:"0.25rem 0.5rem",borderRadius:"0.375rem",fontWeight:"600"},children:["Picked up at: ",task.samplePickedUpTime]})]}),/*#__PURE__*/_jsxs("div",{style:{marginBottom:"1rem"},children:[/*#__PURE__*/_jsx("label",{style:{fontSize:"0.75rem",color:"#64748b",marginBottom:"0.25rem",display:"block"},children:"Remarks"}),/*#__PURE__*/_jsx("input",{type:"text",placeholder:"Enter remarks (optional)",value:task.remarks||"",onChange:e=>handleRemarksChange(index,e.target.value),style:{width:"100%",padding:"0.5rem",borderRadius:"0.5rem",border:"1px solid #d1d5db",fontSize:"0.875rem"}})]}),/*#__PURE__*/_jsx("div",{style:{display:"flex",justifyContent:"flex-end"},children:/*#__PURE__*/_jsxs("button",{onClick:()=>saveTask(index),style:{display:"flex",alignItems:"center",gap:"0.